(()=>{"use strict";let i=self;i.addEventListener("install",t=>{i.skipWaiting()}),i.addEventListener("activate",t=>{t.waitUntil(i.clients.claim())}),i.addEventListener("push",t=>{console.log("\uD83D\uDD25 PUSH 이벤트 수신됨!",t),console.log("\uD83D\uDD25 이벤트 데이터:",t.data);try{let n={};if(t.data)try{n=t.data.json(),console.log("\uD83D\uDD25 JSON 파싱 성공:",n)}catch(o){let n=t.data.text();if(console.log("\uD83D\uDD25 JSON 파싱 실패, 텍스트로 파싱:",n),n){t.waitUntil(i.registration.showNotification("알림",{body:n,icon:"/icons/icon-192x192.png",badge:"/icons/icon-48x48.png"}));return}}console.log("\uD83D\uDD25 최종 파싱된 데이터:",n);let o=n.title||"알림",c={body:n.body||"새 알림이 있습니다",icon:n.icon||"/icons/icon-192x192.png",badge:n.badge||"/icons/icon-48x48.png",tag:n.tag||"stock-cock-notification",data:n.data||{},requireInteraction:!1,silent:!1};console.log("\uD83D\uDD25 알림 표시 시도:",o,c),t.waitUntil(i.registration.showNotification(o,c)),console.log("\uD83D\uDD25 알림 표시 완료")}catch(n){console.error("\uD83D\uDD25 푸시 이벤트 처리 오류:",n),t.waitUntil(i.registration.showNotification("알림",{body:"새 알림이 있습니다",icon:"/icons/icon-192x192.png",badge:"/icons/icon-48x48.png"}))}}),i.addEventListener("notificationclick",t=>{t.notification.close(),t.waitUntil((async()=>{let t=(await i.clients.matchAll({includeUncontrolled:!0,type:"window"})).find(i=>"focus"in i);t?await t.focus():await i.clients.openWindow("/")})())})})();